                      width: '100%',
                      padding: '14px',
                      borderRadius: '14px',
                      background: '#0284c7',
                      color: '#ffffff',
                      border: 'none',
                      fontSize: '0.88rem',
                      fontWeight: 800,
                      cursor: 'pointer',
                      marginBottom: '16px',
                      transition: 'all 0.15s ease'
